// 살아 있나. 가볍게, 의존성 없이
app.get('/livez', (req, res) => res.send('ok'));

// 받을 준비 됐나. 필수 의존성만
app.get('/readyz', async (req, res) => {
  try {
    await db.query('SELECT 1');          // 필수
    if (!cacheWarmed) return res.status(503).send('warming');
    res.send('ok');
  } catch {
    res.status(503).send('db');           // 라우팅에서 빠진다 (재시작은 아님)
  }
});

-- 위험: 큰 테이블에 기본값 있는 NOT NULL 컬럼 추가 (옛 버전 DB 에서 전체 재작성)
ALTER TABLE big ADD COLUMN x int NOT NULL DEFAULT 0;

-- 안전: nullable 로 추가 -> 채우기 -> 제약 추가
ALTER TABLE big ADD COLUMN x int;
UPDATE big SET x = 0 WHERE x IS NULL;   -- 배치로 나눠서
ALTER TABLE big ALTER COLUMN x SET NOT NULL;

-- 인덱스는 온라인으로
